		//#region src/skin-settings.ts
		/**
		* 皮肤偏好的常量与形状（宿主半边与浏览器半边共用）。
		*
		* 记号：皮肤 id 存在 **localStorage**（客户端表现偏好，且要跨标签页实时同步）；
		* 素材目录存在 **settings 的 `ui-skin` 命名空间**（宿主半边要读它来服务文件，
		* localStorage 宿主读不到）。
		*/
		/** 可选皮肤 id（DeepSeek 是产品默认）。 */
		const SKIN_IDS = [
			"deepseek",
			"codex",
			"claude-code"
		];
		/** 设置命名空间（宿主注册 + 客户端读写，必须一致）。 */
		const SKIN_SETTINGS_NAMESPACE = "dsh-ui-skin";
		/** 设置里承载"素材目录"的字段名。 */
		const ASSETS_DIR_FIELD = "assetsDir";
		/** 皮肤 id 字段名（树内形态用它写进设置；外部形态下皮肤走 localStorage，保留此常量供兼容）。 */
		const SKIN_FIELD = "skin";
		/** 没有任何持久化时的默认皮肤。 */
		const DEFAULT_SKIN = "deepseek";
		/** 浏览器端持久化键。 */
		const SKIN_STORAGE_KEY = "dsh.dshUiSkin.skin";
		/** 承载当前皮肤品牌面的 body 属性。 */
		const SKIN_ATTRIBUTE = "data-dsh-ui-skin";
		/**
		* 把一个值收窄成合法皮肤 id。
		* @param value - 跨存储边界的值。
		* @returns 是否是内置皮肤 id。
		*/
		function isSkinId(value) {
			return SKIN_IDS.some((id) => id === value);
		}
		//#endregion
		//#region src/client/skin-row-store.ts
		/**
		* 皮肤设置行的槽位 store：皮肤服务快照 + 素材清单的浏览器镜像。
		* 写入方只有插件的 `skin/change` 监听与素材拉取；行组件通过 props.useStore 读。
		*/
		/**
		* 建一个皮肤设置行的 store。
		* @returns store 句柄。
		*/
		function createSkinRowStore() {
			return createStore({
				skin: DEFAULT_SKIN,
				revision: -1,
				assets: { status: "loading" },
				assetsDir: ""
			});
		}
